const MODEL = 'google/gemini-2.5-flash-lite';

const today = new Date();
const todayStr = today.toISOString().split('T')[0];

const PROMPT = `คุณเป็นระบบวิเคราะห์ข้อความป้อนเข้าสำหรับแอป FridgeMate วันนี้คือวันที่ ${todayStr}
ให้วิเคราะห์ข้อความเสียงหรือข้อความพิมพ์สั่งซื้อวัตถุดิบของผู้ใช้เพื่อแยกแยะรายการวัตถุดิบ 
แล้วตอบกลับเป็นรูปแบบ JSON (ห้ามมีคำนำหรือเครื่องหมาย markdown ใดๆ ทั้งสิ้น):

{
  "items": [
    {
      "name": "<ชื่อวัตถุดิบภาษาไทย>",
      "category": "Meat|Vegetable|Egg|Dairy|Cooked Food|Fruit|Other",
      "quantity": <ตัวเลขจำนวน>,
      "unit": "<หน่วย เช่น แพ็ค/ขวด/ฟอง/ชิ้น/กิโล/ถุง>",
      "expiry_date": "YYYY-MM-DD"
    }
  ]
}

กฎการคำนวณวันหมดอายุสะสมนับจากวันนี้ (${todayStr}):
- Meat (เนื้อสัตว์): 3 วันนับจากวันนี้
- Vegetable (ผักสด): 4 วันนับจากวันนี้
- Dairy (นม/เนย/ชีส): 7 วันนับจากวันนี้
- Egg (ไข่ไก่): 14 วันนับจากวันนี้
- Cooked Food (อาหารปรุงสุก): 3 วันนับจากวันนี้
- Fruit (ผลไม้): 6 วันนับจากวันนี้
- Other (อื่นๆ): 14 วันนับจากวันนี้

ตอบกลับด้วยข้อความ JSON ที่ถูกต้องเท่านั้น ห้ามใส่เครื่องหมายกั้น markdown หรือคำอธิบายเพิ่มเติมใดๆ`;

const text = $json.body?.text ?? $json.text ?? '';

return [{  json: {    body: {      model: MODEL,      messages: [        {          role: 'user',          content: `${PROMPT}\n\nข้อความจากผู้ใช้: "${text}"`        }      ]    }  }}];

const MODEL = 'google/gemini-2.5-flash-lite';

const today = new Date();
const todayStr = today.toISOString().split('T')[0];

const PROMPT = `You are FridgeMate AI, an expert OCR & Receipt Analyzer. Today's date is ${todayStr}.
Analyze the uploaded image (either a food product expiry label or a grocery store purchase receipt).
Identify all items and their expiry dates, then respond with ONLY valid JSON in this exact structure, no markdown, no explanation:

{
  "items": [
    {
      "name": "<Food/Product name in Thai>",
      "category": "Meat|Vegetable|Egg|Dairy|Cooked Food|Fruit|Other",
      "quantity": <number>,
      "unit": "<unit e.g. แพ็ค/ขวด/ฟอง/ชิ้น/กิโล/ถุง>",
      "expiry_date": "YYYY-MM-DD"
    }
  ]
}

Guidelines:
1. Product Expiry Label Scan:
   - Locate any expiration label text (e.g. EXP, BB, BBE, Best Before, หมดอายุ) and extract the expiration date.
   - Convert the date to YYYY-MM-DD format.
2. Grocery Receipt Scan:
   - Extract all food/grocery items purchased, including their quantities and units.
   - For each item, estimate a safe expiry date based on standard shelf life from today's date (${todayStr}):
     - Meat (เนื้อสัตว์): 3 days from now
     - Vegetable (ผัก): 4 days from now
     - Dairy (นม/เนย/ชีส): 7 days from now
     - Egg (ไข่): 14 days from now
     - Cooked Food (อาหารปรุงสำเร็จ): 3 days from now
     - Fruit (ผลไม้): 6 days from now
     - Other (อื่นๆ): 14 days from now
   - Set the calculated date in "expiry_date".

Respond ONLY with valid JSON. Do not include markdown code fences.`;

const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
const binaryKey = binaryKeys.includes('photo') ? 'photo' : (binaryKeys[0] || 'photo');
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const mime = item.binary?.[binaryKey]?.mimeType || 'image/jpeg';
const dataUrl = `data:${mime};base64,${buffer.toString('base64')}`;

return [{
  json: {
    body: {
      model: MODEL,
      messages: [
        {
          role: 'user',
          content: [
            { type: 'text', text: PROMPT },
            { type: 'image_url', image_url: { url: dataUrl } }
          ]
        }
      ]
    }
  }
}];

const raw = $input.first().json;

let text = raw.choices?.[0]?.message?.content
  ?? raw.content ?? raw.text ?? raw.output ?? raw.response ?? '';
if (typeof text !== 'string') {
  text = JSON.stringify(text);
}

if (!text && raw.error) {
  return [{ json: {
    items: [],
    error: true,
    note_th: 'AI ขัดข้อง: ' + (raw.error.message || 'unknown error')
  } }];
}

let cleaned = text.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) {}
  }
}

if (!parsed || typeof parsed !== 'object') {
  parsed = {
    items: [],
    error: true,
    note_th: 'ไม่สามารถอ่านผลวิเคราะห์จาก AI ได้'
  };
}

return [{ json: parsed }];

const payload = $input.first().json.body || {};
const hh = payload.household_id || 'HOME123';
const itemsList = payload.items || [];

const redItems = itemsList.filter(i => i.days_left <= 1);
const yellowItems = itemsList.filter(i => i.days_left > 1 && i.days_left <= 4);

let messageParts = [`\n[แจ้งเตือนตู้เย็น - บ้าน ${hh}] 🔔`];

if (redItems.length > 0) {
    const redLines = redItems.map(i => {
        const days = i.days_left;
        const status = days < 0 ? `หมดอายุแล้ว ${Math.abs(days)} วัน` : (days === 0 ? 'หมดอายุวันนี้' : 'เหลือ 1 วัน');
        return `- ${i.name} (${i.quantity} ${i.unit}) [${status}]`;
    }).join('\n');
    messageParts.push(`🔴 โซนรีบกิน (หมดอายุใน 1 วัน):\n${redLines}`);
} else {
    messageParts.push(`🔴 โซนรีบกิน: ไม่มีรายการวัตถุดิบใกล้หมดอายุ`);
}

if (yellowItems.length > 0) {
    const yellowLines = yellowItems.map(i => `- ${i.name} (${i.quantity} ${i.unit}) [เหลือ ${i.days_left} วัน]`).join('\n');
    messageParts.push(`\n🟡 โซนใกล้หมดอายุ (หมดอายุใน 2-4 วัน):\n${yellowLines}`);
} else {
    messageParts.push(`\n🟡 โซนใกล้หมดอายุ: ไม่มีรายการวัตถุดิบใกล้หมดอายุ`);
}

const message = messageParts.join('\n');
return [{ json: { message } }];

const body = $input.first().json.body || {};
const events = body.events || [];
if (events.length === 0) {
    return [{ json: { is_valid: false } }];
}

const event = events[0];
const source = event.source || {};
const lineId = source.groupId || source.userId || '';
const replyToken = event.replyToken || '';
const message = event.message || {};
const msgType = message.type || '';

let isCommand = false;
let commandType = '';
let targetHouseholdId = '';
let textContent = '';

if (msgType === 'text') {
    textContent = (message.text || '').trim();
    if (textContent.startsWith('เชื่อมบ้าน ')) {
        isCommand = true;
        commandType = 'LINK_HOUSEHOLD';
        targetHouseholdId = textContent.replace('เชื่อมบ้าน ', '').trim();
    } else if (textContent.toLowerCase().startsWith('set household ')) {
        isCommand = true;
        commandType = 'LINK_HOUSEHOLD';
        targetHouseholdId = textContent.replace(/set household /i, '').trim();
    }
}

return [{
    json: {
        is_valid: true,
        lineId,
        replyToken,
        msgType,
        isCommand,
        commandType,
        targetHouseholdId,
        textContent,
        messageId: message.id || ''
    }
}];

